					content, ok := source.read(filePath)
					if ok { selection.filesContentRead++ }
					// Preserve unreadable files so normal indexing reports their failure.
					if !ok || textMatchesSearchQuery(q, content) {
						filtered = append(filtered, filePath)
					}
				}
				files = filtered
			}
			selection.files = bridgeRegistrationHandlerFiles(ctx, source, files, searchRegistrationBridgeMaxHandlers)''';assert old in s;s=s.replace(old,new,1);open(p,'w').write(s)
PY
