 } { t.Run(tc.query, func(t *testing.T) { if got := buildSearchQuery(tc.query).termSet["login"]; got != tc.want {t.Fatalf("login = %v, want %v",got,tc.want)} }) }
 t.Run("deep expansion", func(t *testing.T) {
  q := buildSparseSearchQuery("authentication logs a user in")
  if !q.termSet["auth"] || !q.termSet["login"] { t.Fatalf("missing deep query expansions: %v",q.terms) }
 })
}
