		if textEnd < 0 {
			textEnd = len(data)
		}
		matches = append(matches, GrepMatch{Path: path, Text: string(data[:textEnd])})
		if textEnd == len(data) {
			data = nil
		} else {
			data = data[textEnd+1:]
		}
	}
	return matches, nil
}

