		return searchCandidate{}, false
	}
	base += searchPathPrior(q, filePath)
	return searchCandidate{
		result: SearchResult{
			FilePath:         filePath,
			StartLine:        start,
			EndLine:          end,
		matches := 0.0
		for _, term := range q.terms {
			if searchQueryTermMatches(q, lines[line-1], lower, term) {
