 cmd:=newGitCmdWithCallerLocale(ctx,repo,args...)
 var stderr bytes.Buffer
 cmd.Stderr=&stderr
 stdout,err:=cmd.StdoutPipe()
 if err!=nil {return err}
 if err=cmd.Start();err!=nil {return err}
 reader:=bufio.NewReader(stdout)
